fn solve(a: i8, b: i8, c: i8) -> i8 {
    let mut v = [a as i32, b as i32, c as i32];
    v.sort();
    let x = v[0];
    let y = v[1];
    let z = v[2];

    // Each operation increases the total sum by exactly 2.
    // We need to reach (t, t, t) for some t >= z with matching parity of sums:
    // 3t - (x+y+z) must be even.
    let s = x + y + z;

    let mut t = z;
    while ((3 * t - s) & 1) != 0 {
        t += 1;
    }

    // For fixed t, let di = t - v[i]. Each move reduces either:
    // - one di by 2 (increase one number by 2), or
    // - two di by 1 each (increase two numbers by 1).
    // Minimum operations is max(max(di), sum(di)/2).
    let d1 = t - x;
    let d2 = t - y;
    let d3 = t - z;
    let sum_d = d1 + d2 + d3;
    let max_d = d1.max(d2).max(d3);

    let ops = max_d.max(sum_d / 2);
    ops as i8
}